function check_if_mobile(e,t,n){window.matchMedia("(max-width: 600px)").matches?fetch(t).then((e=>{if(e.ok)return e.text()})).then((t=>{e.innerHTML=t})):(console.log("Sidebar.js: This is a Desktop device."),fetch(n).then((e=>{if(e.ok)return e.text()})).then((t=>{e.innerHTML=t})))}function setfooter(e,t){fetch(t).then((e=>{if(e.ok)return e.text()})).then((t=>{e.innerHTML=desktopsnippet}))}window.onload=function(){const e=document.querySelector(".sidebar");htmlSnippetmobile="./snippets/dropdownsidebar.html",htmlSnippetdesktop="./snippets/sidebar.html",check_if_mobile(e,htmlSnippetmobile,htmlSnippetdesktop)};